<script setup>
import {computed,nextTick,ref} from 'vue'
import {sampleSteps,symbolExamples,pictureInput,wrap,unwrap,filenameJourney,readChoices,transferChoices} from './encoding-sample.js'
const screen=ref(0),furthest=ref(0),night=ref(false),sent=ref(false),symbol=ref(0),decoded=ref(false),tried=ref([]),answer=ref(null),layers=ref(0),journeyStep=ref(0),fixed=ref(false),transfer=ref(null),placement=ref(null)
const selected=computed(()=>symbolExamples[symbol.value])
const journey=computed(()=>filenameJourney('folder%252Fphoto.png',fixed.value))
const layerValues=computed(()=>['/',wrap('/'),wrap(wrap('/'))])
const layerPhase=computed(()=>['Start with a slash','Encode it once','Encode that result again','Decode once','Decode once more'][layers.value])
const layerCurrent=computed(()=>[layerValues.value[0],layerValues.value[1],layerValues.value[2],unwrap(layerValues.value[2]),unwrap(unwrap(layerValues.value[2]))][layers.value])
const complete=computed(()=>[sent.value,tried.value.length>=2,answer.value!==null&&readChoices[answer.value].correct,layers.value===4,journeyStep.value===4&&fixed.value,transfer.value!==null&&transferChoices[transfer.value].correct&&placement.value==='last',true][screen.value])
const headings=['Why does %20 become a space?','Same character. Different spelling.','Can you read this filename?','What if we encode it twice?','A check can read the wrong version.','Take the idea somewhere new.','You can now follow the change.']
async function navigate(index){screen.value=index;furthest.value=Math.max(furthest.value,index);await nextTick();const title=document.getElementById('sample-title');title?.focus({preventScroll:true});title?.scrollIntoView({block:'start',behavior:'auto'})}
function chooseSymbol(index){symbol.value=index;decoded.value=false}
function decodeSymbol(){decoded.value=true;if(!tried.value.includes(symbol.value))tried.value.push(symbol.value)}
function restart(){sent.value=false;symbol.value=0;decoded.value=false;tried.value=[];answer.value=null;layers.value=0;journeyStep.value=0;fixed.value=false;transfer.value=null;placement.value=null;furthest.value=0;navigate(0)}
</script>
<template>
<div class="encoding-sample" :class="{'sample-night':night}">
 <header class="sample-header"><a href="#/learn/encoding/0" class="sample-brand"><span class="sample-mark" aria-hidden="true">w.</span><span>websec<span class="sample-brand-note">a learning workshop</span></span></a><div><span class="sample-edition">One-topic sample</span><button class="sample-appearance" :aria-label="night?'Use light appearance':'Use dark appearance'" @click="night=!night">{{night?'☀':'◐'}}</button></div></header>
 <div class="sample-wrap">
  <div class="sample-topline"><span>TOPIC 02 <i>/</i> Encoding, from zero</span><button @click="restart">Start again ↺</button></div>
  <nav class="sample-progress" aria-label="Sample steps"><ol><li v-for="(name,index) in sampleSteps" :key="name"><button :disabled="index>furthest" :aria-label="'Step '+(index+1)+': '+name" :aria-current="screen===index?'step':undefined" :class="{visited:index<furthest}" @click="navigate(index)"><span>{{index<furthest?'✓':index+1}}</span></button></li></ol><span>{{screen+1}} of {{sampleSteps.length}} <b>{{sampleSteps[screen]}}</b></span></nav>
  <section class="sample-lesson" :data-sample-step="screen">
   <div class="sample-copy">
    <span class="sample-kicker">{{['LET’S SEE IT HAPPEN','GIVE THE CHANGE A NAME','A SMALL CHECK','ONE LAYER AT A TIME','WHY THIS MATTERS','YOUR TURN','A PLACE TO PAUSE'][screen]}}</span>
    <h1 id="sample-title" tabindex="-1">{{headings[screen]}}</h1>
    <template v-if="screen===0"><p>A photo app receives <code>blue%20sky.png</code>, but opens a file called <code>blue sky.png</code>.</p><p>Where did the <code>%20</code> go? Send the filename and watch the app read it.</p><div class="sample-goal"><span>In this short lesson</span>You’ll learn to read simple URL codes, unwrap them one layer at a time, and spot when two parts of an app see different text.</div></template>
    <template v-else-if="screen===1"><p><strong>URL encoding</strong> writes some characters using a <code>%</code> sign and two digits or letters.</p><p>For a space, that spelling is <code>%20</code>. <strong>Decoding</strong> turns the spelling back into the original character.</p><p class="sample-instruction">Choose a character, then press Decode. Try at least two.</p><details class="sample-detail"><summary>Why do URLs need this?</summary><p>Some characters have special jobs in a URL. Encoding lets you represent them inside a value. It changes how the text is written; it does not hide it with a secret key.</p><p>These examples each represent one byte. The two characters after % are a hexadecimal number. You don’t need to memorize that number system for this lesson.</p></details></template>
    <template v-else-if="screen===2"><p>The app receives the filename on the right and decodes it <strong>once</strong>.</p><p>Choose the filename it will see. If you’re unsure, go back and try the space example again.</p><div class="sample-reminder"><span>A reminder</span><code>%20</code> → one space</div></template>
    <template v-else-if="screen===3"><p>Now start with a slash: <code>/</code>. Encode it once, then encode the result again.</p><p>Watch the <code>%</code> sign carefully. It has its own code: <code>%25</code>.</p><p class="sample-instruction">Use the blue button to make each change yourself.</p></template>
    <template v-else-if="screen===4"><p>This photo app has a rule: <strong>filenames must not contain a slash</strong>.</p><p>But two parts of this example app each decode once. We’ll call them readers: each turns URL codes back into characters.</p><p>Follow <code>folder%252Fphoto.png</code> through both readers. See which version the rule checks.</p><details class="sample-detail"><summary>Is every app built this way?</summary><p>No. We deliberately use two readers here to make the order visible. In a real challenge, you need evidence of how many decoding steps actually happen. Double encoding alone does not bypass a rule.</p></details></template>
    <template v-else-if="screen===5"><p>A different app receives <code>reports%252F2026.txt</code>. This app decodes it <strong>only once</strong>.</p><p>Use the idea you just learned to predict what it sees.</p><div class="sample-reminder"><span>The useful question</span>“What text does this part of the app actually receive?”</div></template>
    <template v-else><p>You started with an unfamiliar code. Now you can explain how its meaning changes as an app reads it.</p><p>This sample stops here so we can improve the experience together before expanding it.</p><div class="sample-goal"><span>Your feedback shapes the next version</span>Tell me which step made sense, where you had to guess, and how the new look felt. Step numbers make it easy to point to a moment.</div></template>
   </div>
   <div class="sample-workbench">
    <section v-if="screen===0" class="sample-card">
     <div class="sample-card-heading"><span class="sample-dot"></span><h2>A tiny photo app</h2><span class="sample-card-note">click to try</span></div>
     <div class="sample-field"><span>Filename sent to the app</span><code>blue<mark>%20</mark>sky.png</code></div>
     <button v-if="!sent" class="sample-primary" @click="sent=true">Send this filename <span>→</span></button>
     <template v-else><div class="sample-down">↓ the app decodes the filename</div><div class="sample-field sample-revealed"><span>The filename it reads</span><code>blue<mark class="sample-space" aria-label="space">␣</mark>sky.png</code><small>␣ marks a space so you can see it.</small></div><div class="sample-photo"><svg viewBox="0 0 400 125" role="img" aria-label="A blue sky above hills"><rect width="400" height="125" fill="#b9ddf6"/><circle cx="316" cy="34" r="18" fill="#fff1b8"/><path d="M0 106 Q85 22 197 113 L260 125 H0" fill="#76a791"/><path d="M150 125 Q295 32 400 104 V125" fill="#4e8377"/><path d="M48 39h65m-42-9h62" stroke="#fff" stroke-width="9" stroke-linecap="round"/></svg><span>Opened <strong>{{unwrap(pictureInput)}}</strong></span></div><div class="sample-feedback" role="status"><strong>There’s the change.</strong><p><code>%20</code> became a space. That lets the app find <code>blue sky.png</code>. The name has a different spelling on the way in.</p></div></template>
    </section>
    <section v-else-if="screen===1" class="sample-card"><div class="sample-card-heading"><span class="sample-dot"></span><h2>A tiny code reader</h2></div><div class="sample-symbols" role="group" aria-label="Choose a character"><button v-for="(example,index) in symbolExamples" :key="example.label" :aria-pressed="symbol===index" @click="chooseSymbol(index)">{{example.label}}<span v-if="tried.includes(index)">✓</span></button></div><div class="sample-code-pair"><div><span>URL spelling</span><code>{{wrap(selected.plain)}}</code></div><span aria-hidden="true">→</span><div :class="{'sample-result-ready':decoded}"><span>Original character</span><code>{{decoded?(selected.plain===' '?'␣':selected.plain):'?'}}</code><small v-if="decoded&&selected.plain===' '">one space</small></div></div><button class="sample-primary" :disabled="decoded" @click="decodeSymbol">{{decoded?'Decoded':'Decode '+selected.encoded}} <span>{{decoded?'✓':'→'}}</span></button><div v-if="decoded" class="sample-feedback" role="status"><strong>{{selected.encoded}} means {{selected.plain===' '?'a space':selected.plain==='/'?'a slash':'a percent sign'}}.</strong><p>The whole group <code>{{selected.encoded}}</code> is replaced with one character. {{tried.length<2?'Choose another character above to try a second example.':'You’ve tried more than one spelling. Ready for a small check?'}}</p></div></section>
    <section v-else-if="screen===2" class="sample-card"><div class="sample-card-heading"><span class="sample-dot"></span><h2>One decoding pass</h2></div><div class="sample-field"><span>Received</span><code>holiday<mark>%20</mark>photo.png</code></div><h3 class="sample-question">Which filename comes out?</h3><div class="sample-choices"><button v-for="(choice,index) in readChoices" :key="choice.text" :aria-pressed="answer===index" :class="{'sample-chosen':answer===index}" @click="answer=index"><span>{{String.fromCharCode(65+index)}}</span><code>{{choice.text}}</code><b v-if="answer===index">{{choice.correct?'✓':'↻'}}</b></button></div><div v-if="answer!==null" class="sample-feedback" :class="{'sample-retry':!readChoices[answer].correct}" role="status"><strong>{{readChoices[answer].correct?'You read it correctly.':'Let’s follow that code again.'}}</strong><p>{{readChoices[answer].feedback}}</p></div></section>
    <section v-else-if="screen===3" class="sample-card"><div class="sample-card-heading"><span class="sample-dot"></span><h2>The wrapping table</h2><button v-if="layers>0" class="sample-text-button" @click="layers=0">Replay ↺</button></div><div class="sample-layer-stack"><div :class="{active:layers===0||layers===4}"><span>Original</span><code>/</code></div><div v-if="layers>=1" :class="{active:layers===1||layers===3}"><span>One layer</span><code>%2F</code></div><div v-if="layers>=2" :class="{active:layers===2}"><span>Two layers</span><code><mark>%25</mark>2F</code></div></div><div class="sample-current"><span>{{layerPhase}}</span><code>{{layerCurrent}}</code></div><button v-if="layers<4" class="sample-primary" @click="layers++">{{['Encode / once','Encode %2F again','Decode %252F once','Decode %2F once'][layers]}} <span>{{layers<2?'↗':'↙'}}</span></button><div v-if="layers>0" class="sample-feedback" role="status"><strong>{{['','/ became %2F.','The percent sign got encoded.','One layer came off.','Now the slash is back.'][layers]}}</strong><p>{{['','That is one URL-encoded layer. Now try encoding this result.','In %2F, the % became %25. The 2F stayed as it was. Together, that makes %252F.','%25 became %. The result is %2F, not / yet. A decoding pass does not repeatedly decode its own result.','It took two decoding passes to turn %252F back into /. The number of readers matters.'][layers]}}</p></div></section>
    <section v-else-if="screen===4" class="sample-card"><div class="sample-card-heading"><span class="sample-dot"></span><h2>Inside the photo app</h2><span class="sample-card-note">{{fixed?'check moved':'follow the text'}}</span></div><div class="sample-pipeline"><div class="sample-pipe-row"><span class="sample-pipe-number">→</span><div><small>Received filename</small><code>{{journey.raw}}</code></div></div><div class="sample-pipe-row" :class="{pending:journeyStep<1}"><span class="sample-pipe-number">1</span><div><small>First reader · decode once</small><code>{{journeyStep>=1?journey.first:'Waiting for your click'}}</code></div></div><div v-if="!fixed" class="sample-pipe-row sample-rule" :class="{pending:journeyStep<2}"><span class="sample-pipe-number">✓</span><div><small>Check: no / in the filename</small><code>{{journeyStep>=2?'No slash found → allowed':'Not checked yet'}}</code><p v-if="journeyStep>=2">It checks <code>{{journey.first}}</code>.</p></div></div><div class="sample-pipe-row" :class="{pending:journeyStep<3}"><span class="sample-pipe-number">2</span><div><small>Second reader · decode once</small><code>{{journeyStep>=3?journey.final:'Waiting for the earlier steps'}}</code></div></div><div v-if="fixed" class="sample-pipe-row sample-rule sample-rule-blocked"><span class="sample-pipe-number">!</span><div><small>Check: no / in the final filename</small><code>{{journey.allowed?'Allowed':'Slash found → stopped'}}</code><p>It checks <code>{{journey.checked}}</code>.</p></div></div></div><button v-if="journeyStep<3" class="sample-primary" @click="journeyStep++">{{['Run the first reader','Run the filename check','Run the second reader'][journeyStep]}} <span>→</span></button><button v-else-if="!fixed" class="sample-primary" @click="fixed=true;journeyStep=4">Move the check after the last reader <span>↓</span></button><div v-if="journeyStep>0" class="sample-feedback" :class="{'sample-retry':journeyStep===3}" role="status"><strong>{{fixed?'Now the check sees the final text.':journeyStep===1?'The first reader leaves %2F.':journeyStep===2?'It passes—but look at the next reader.':'A slash appeared after the check.'}}</strong><p>{{fixed?'The final filename contains /. The rule stops it because it now checks the same version the app would use.':journeyStep===1?'Only %25 turned into %. We still have an encoded slash.':journeyStep===2?'The check looked for a literal /, but saw %2F instead. Now run the second reader.':'The rule approved one spelling, then another reader changed its meaning. Move the check to see how the decision changes.'}}</p></div></section>
    <section v-else-if="screen===5" class="sample-card"><div class="sample-card-heading"><span class="sample-dot"></span><h2>A new filename</h2></div><div class="sample-field"><span>Decode exactly once</span><code>reports<mark>%25</mark>2F2026.txt</code></div><h3 class="sample-question">What does the app see?</h3><div class="sample-choices"><button v-for="(choice,index) in transferChoices" :key="choice.text" :aria-pressed="transfer===index" :class="{'sample-chosen':transfer===index}" @click="transfer=index;placement=null"><span>{{String.fromCharCode(65+index)}}</span><code>{{choice.text}}</code></button></div><div v-if="transfer!==null" class="sample-feedback" :class="{'sample-retry':!transferChoices[transfer].correct}" role="status"><strong>{{transferChoices[transfer].correct?'One pass, one layer.':'Count the decoding passes.'}}</strong><p>{{transferChoices[transfer].feedback}}</p></div><template v-if="transfer!==null&&transferChoices[transfer].correct"><h3 class="sample-question">If another reader decodes it again, where should the no-slash check go?</h3><div class="sample-choices"><button :aria-pressed="placement==='first'" @click="placement='first'">Before the second reader</button><button :aria-pressed="placement==='last'" @click="placement='last'">After the final reader</button></div><div v-if="placement" class="sample-feedback" :class="{'sample-retry':placement!=='last'}" role="status"><strong>{{placement==='last'?'You connected the two ideas.':'That leaves a change after the check.'}}</strong><p>{{placement==='last'?'Check the final interpretation that the app will use. Encoding changes spelling; decoding order determines which spelling a rule sees.':'The second reader could introduce a slash after approval. The rule needs to check the final filename.'}}</p></div></template></section>
    <section v-else class="sample-card sample-finish"><span class="sample-finish-mark">✓</span><h2>Three ideas to take with you.</h2><ol><li><b>Encoding changes the spelling.</b><span><code>%20</code> represents a space. <code>%2F</code> represents a slash.</span></li><li><b>One pass removes one layer.</b><span><code>%252F → %2F → /</code> takes two passes.</span></li><li><b>The order changes what a rule sees.</b><span>Check the final interpretation, rather than an earlier spelling that can still change.</span></li></ol><div class="sample-feedback"><strong>No codes to memorize.</strong><p>The habit to keep: follow the text through each reader and ask what changed.</p></div><button class="sample-primary" @click="restart">Try the sample again <span>↺</span></button></section>
   </div>
  </section>
  <footer class="sample-controls"><button v-if="screen>0" class="sample-back" @click="navigate(screen-1)">← Back</button><span v-else class="sample-back">Nothing to install. No typing needed.</span><div v-if="screen<sampleSteps.length-1"><small v-if="!complete">{{['Send the filename to see what changes.','Decode two characters to continue.','Choose a filename to check your understanding.','Try each change at the wrapping table.','Run both readers, then move the check.','Answer both questions to continue.'][screen]}}</small><button class="sample-primary" :disabled="!complete" @click="navigate(screen+1)">{{screen===5?'Let’s review':'Continue'}} <span>→</span></button></div><a v-else href="#/learn/encoding/0">Back to the topic ↗</a></footer>
  <p class="sample-footnote">A small, browser-only teaching example. Your existing lesson and lab records stay separate.</p>
 </div>
</div>
</template>
